package io.tenvyr.control.runtime;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.*;
import io.tenvyr.platform.*;
import java.time.Instant;
import java.util.*;
/** A read projection: resolving an item always uses its original authority route. */
public final class AttentionService {
    private final Db db;public AttentionService(Db db){this.db=db;}
    public ObjectNode attention(){List<ObjectNode> runs=db.query("SELECT * FROM coordination_runs"),executions=db.query("SELECT e.* FROM executions e JOIN coordination_runs r ON r.\"executionId\"=e.id"),approvals=db.query("SELECT * FROM approval_requests WHERE status='PENDING'"),leases=db.query("SELECT * FROM workspace_executions WHERE state='PRESERVED'");return Json.object("items",deriveAttentionItems(runs,executions,approvals,leases),"serverTime",Instant.now().toString());}
    public static ArrayNode deriveAttentionItems(List<ObjectNode> runs,List<ObjectNode> executions,List<ObjectNode> approvals,List<ObjectNode> leases){Map<String,ObjectNode> byExecution=new HashMap<>(),byRun=new HashMap<>();for(ObjectNode run:runs){byExecution.put(Json.text(run,"executionId"),run);byRun.put(Json.text(run,"id"),run);}List<ObjectNode> items=new ArrayList<>();for(ObjectNode run:runs){String phase=Json.text(run,"phase"),execution=Json.text(run,"executionId"),id=Json.text(run,"id");if(phase.equals("WAITING_FOR_HUMAN"))items.add(item("HUMAN_APPROVAL_REQUIRED","critical",execution,id,Json.text(run,"waitReason","Verifier requires operator decision"),run,"/runs/"+execution,null));else if(phase.equals("LIMIT_REACHED"))items.add(item("LIMIT_REACHED","warning",execution,id,"Iteration or worker limits reached",run,"/runs/"+execution,null));}for(ObjectNode request:approvals)if(Json.text(request,"status").equals("PENDING")){ObjectNode v=item("HUMAN_APPROVAL_REQUIRED","warning",null,null,"Policy approval required: "+Json.text(request,"actionType")+(request.hasNonNull("targetAgent")?" for "+Json.text(request,"targetAgent"):""),request,"/approvals",null);v.put("attentionId",attentionId("HUMAN_APPROVAL_REQUIRED",Json.text(request,"proposalId")));v.set("updatedAt",request.get("createdAt"));items.add(v);}for(ObjectNode execution:executions)if(Json.text(execution,"status").equals("FAILED")){String id=Json.text(execution,"id");ObjectNode run=byExecution.get(id);items.add(item("RUN_FAILED","warning",id,run==null?null:Json.text(run,"id"),Json.text(execution,"terminationReason","Worker execution failed"),execution,"/runs/"+id,null));}for(ObjectNode lease:leases)if(Json.text(lease,"state").equals("PRESERVED")&&!Boolean.FALSE.equals(lease.hasNonNull("hasUncommittedWork")?lease.path("hasUncommittedWork").asBoolean():null)){String owner=Json.text(lease,"ownerRunId",null);ObjectNode run=byRun.get(owner);String execution=run==null?null:Json.text(run,"executionId");items.add(item("WORKSPACE_REQUIRES_ATTENTION","info",execution,owner,lease.hasNonNull("hasUncommittedWork")?"Run finished with uncommitted work in its preserved execution workspace":"Run finished with unknown status in its preserved execution workspace",lease,execution==null?"/workspaces":"/runs/"+execution,Json.text(lease,"id")));}Map<String,Integer> rank=Map.of("critical",0,"warning",1,"info",2);items.sort(Comparator.comparingInt((ObjectNode n)->rank.get(Json.text(n,"severity"))).thenComparing(n->Json.text(n,"updatedAt",""),Comparator.reverseOrder()).thenComparing(n->Json.text(n,"attentionId")));ArrayNode out=Json.array();items.stream().limit(200).forEach(out::add);return out;}
    public static String attentionId(String kind,String id){return "attention:"+kind.toLowerCase(Locale.ROOT)+":"+id;}
    private static ObjectNode item(String kind,String severity,String execution,String run,String reason,JsonNode row,String route,String workspace){ObjectNode result=Json.object("attentionId",attentionId(kind,run!=null?run:execution!=null?execution:workspace!=null?workspace:"?"),"kind",kind,"severity",severity,"executionId",execution,"runId",run,"reason",HandoffService.truncate(reason,512),"createdAt",row.get("createdAt"),"updatedAt",row.get("updatedAt"),"actionRoute",route);if(workspace!=null)result.put("workspaceExecutionId",workspace);return result;}
}
